66	pub fn markdown(path: &Path) -> bool {
67	    path.extension()
68	        .and_then(|s| s.to_str())
69	        .is_some_and(|s| s.eq_ignore_ascii_case("md") || s.eq_ignore_ascii_case("markdown"))
70	}
