72	pub fn supported_document(path: &Path) -> bool {
73	    markdown(path)
74	        || path
75	            .extension()
76	            .and_then(|s| s.to_str())
77	            .is_some_and(|s| matches!(s.to_ascii_lowercase().as_str(), "html" | "htm" | "mdx"))
78	}
