84	// Resolve the parent even when a watched file has been deleted.
85	pub fn identity(path: &Path) -> Result<PathBuf> {
86	    if path.exists() {
87	        return canonical(path);
88	    }
89	    let parent = canonical(path.parent().ok_or("Missing parent directory")?)?;
90	    Ok(parent.join(path.file_name().ok_or("Missing file name")?))
91	}
