167	#[tauri::command]
168	pub async fn open_document(
169	    app: AppHandle,
170	    state: State<'_, Service>,
171	    path: PathBuf,
172	) -> Result<Opened> {
173	    let mut inner = state.0.lock().unwrap();
174	    let path = inner.allowed(&path)?;
175	    if !files::supported_document(&path) {
176	        return Err("Not a supported Sidelit document".into());
177	    }
178	    let snapshot = files::snapshot(&path)?;
179	    inner.open.insert(path.clone());
180	    inner.watches(&app)?;
181	    let parent = path.parent().ok_or("Missing parent")?.to_path_buf();
182	    // A selected document grants browsing its parent, but not arbitrary ancestors.
183	    inner.roots.insert(parent.clone());
184	    Ok(Opened {
185	        path,
186	        snapshot,
187	        parent,
188	    })
189	}
