273	pub async fn save_copy(
274	    app: AppHandle,
275	    state: State<'_, Service>,
276	    path: Option<PathBuf>,
277	    text: String,
278	) -> Result<Option<Opened>> {
279	    if let Some(path) = &path {
280	        state.0.lock().unwrap().registered(path)?;
281	    }
282	    let name = path
283	        .as_ref()
284	        .map(|p| {
285	            format!(
286	                "{}-copy.{}",
287	                p.file_stem().unwrap_or_default().to_string_lossy(),
288	                p.extension().unwrap_or_default().to_string_lossy()
289	            )
290	        })
291	        .unwrap_or_else(|| "Untitled.md".into());
292	    let selected = app
293	        .dialog()
294	        .file()
295	        .set_file_name(name)
296	        .add_filter("Documents", &["md", "markdown", "mdx", "html", "htm"])
297	        .blocking_save_file();
298	    let Some(selected) = selected else {
299	        return Ok(None);
300	    };
301	    let mut inner = state.0.lock().unwrap();
302	    let opened = create_selected(
303	        &mut inner,
304	        &selected.into_path().map_err(|e| e.to_string())?,
305	        &text,
306	    )?;
307	    if let Err(error) = inner.watches(&app) {
308	        let _ = app.emit("service-error", error);
309	    }
310	    Ok(Some(opened))
311	}
