313	fn create_selected(inner: &mut Inner, selected: &Path, text: &str) -> Result<Opened> {
314	    let target = files::identity(selected)?;
315	    if !files::supported_document(&target) {
316	        return Err("Use a .md, .markdown, .mdx, .html, or .htm extension".into());
317	    }
318	    if target.exists() {
319	        return Err("Choose a new file name; no existing file was overwritten.".into());
320	    }
321	    files::atomic_write(&target, text, true)?;
322	    let snapshot = files::text_snapshot(text);
323	    let parent = target.parent().unwrap().to_path_buf();
324	    inner.grants.insert(target.clone());
325	    inner.roots.insert(parent.clone());
326	    inner.open.insert(target.clone());
327	    Ok(Opened {
328	        path: target,
329	        parent,
330	        snapshot,
331	    })
332	}
