338	    document: PathBuf,
339	    reference: String,
340	) -> Result<String> {
341	    let mut inner = state.0.lock().unwrap();
342	    let doc = inner.document(&document)?;
343	    let base = url::Url::from_file_path(&doc).map_err(|_| "Invalid document path")?;
344	    let target = base.join(&reference).map_err(|e| e.to_string())?;
345	    if target.scheme() != "file" {
346	        return Err("Remote images are disabled".into());
347	    }
348	    let target = files::canonical(&target.to_file_path().map_err(|_| "Invalid image path")?)?;
349	    if !target.starts_with(doc.parent().unwrap())
350	        && !inner.roots.iter().any(|r| target.starts_with(r))
351	    {
352	        return Err("Image is outside the authorized folders".into());
353	    }
354	    let ext = target
355	        .extension()
356	        .unwrap_or_default()
357	        .to_string_lossy()
358	        .to_lowercase();
359	    let mime = match ext.as_str() {
360	        "png" => "image/png",
361	        "jpg" | "jpeg" => "image/jpeg",
362	        "gif" => "image/gif",
363	        "webp" => "image/webp",
364	        _ => return Err("Only PNG, JPEG, GIF and WebP images are allowed".into()),
365	    };
366	    let parent = target.parent().ok_or("Missing image parent")?.to_path_buf();
367	    let paths = inner.assets.entry(doc).or_default();
368	    if paths.len() >= 128 && !paths.contains(&parent) {
369	        return Err("Image directory limit reached".into());
370	    }
371	    paths.insert(parent);
372	    inner.watches(&app)?;
373	    drop(inner);
374	    let bytes = files::read_bytes(&target, files::MAX_BYTES)?;
375	    Ok(format!(
376	        "data:{mime};base64,{}",
377	        base64::engine::general_purpose::STANDARD.encode(bytes)
378	    ))
379	}
