569	#[tauri::command]
570	pub async fn restore_session(
571	    app: AppHandle,
572	    state: State<'_, Service>,
573	    recovery: State<'_, Recovery>,
574	) -> Result<Option<Session>> {
575	    let session = recovery
576	        .0
577	        .lock()
578	        .unwrap()
579	        .load(&recovery_path(&app)?)?
580	        .session
581	        .clone();
582	    let Some(mut session) = session else {
583	        return Ok(None);
584	    };
585	    let mut folders: Vec<_> = session
586	        .documents
587	        .iter()
588	        .filter_map(|d| d.path.parent())
589	        .map(|p| p.display().to_string())
590	        .collect();
591	    if let Some(root) = &session.workspace {
592	        folders.push(root.display().to_string());
593	    }
594	    folders.sort();
595	    folders.dedup();
596	    if !app.dialog().message(format!("Restore {} tabs and permit access to these folders?\n\n{}\n\nDrafts will not overwrite files. Changed files will show a conflict.", session.documents.len(), folders.join("\n")))
597	        .title("Restore Sidelit session").buttons(MessageDialogButtons::OkCancel).blocking_show() {
598	        return Ok(None);
599	    }
600	    let mut inner = state.0.lock().unwrap();
601	    for doc in &session.documents {
602	        inner.grants.insert(doc.path.clone());
603	        inner.open.insert(doc.path.clone());
604	        if let Some(parent) = doc.path.parent() {
605	            inner.roots.insert(parent.into());
606	        }
607	    }
608	    if let Some(root) = &session.workspace {
609	        if root.is_dir() && files::canonical(root).is_ok_and(|p| p == *root) {
610	            inner.roots.insert(root.clone());
611	        } else {
612	            session.workspace = None;
613	        }
614	    }
615	    if let Err(error) = inner.watches(&app) {
616	        let _ = app.emit("service-error", error);
617	    }
618	    Ok(Some(session))
619	}
