99	pub(crate) fn safe_id(id: &str) -> bool {
100	    !id.is_empty()
101	        && id.len() <= 128
102	        && id
103	            .bytes()
104	            .all(|byte| byte.is_ascii_alphanumeric() || b"-_:.".contains(&byte))
105	}
