107	fn compatible(project: Option<&str>, target: &str) -> bool {
108	    let Some(project) = project.filter(|value| !value.is_empty()) else {
109	        return true;
110	    };
111	    project == target
112	        || Path::new(project).starts_with(target)
113	        || Path::new(target).starts_with(project)
114	}
