188	fn rex_json(args: &[&str]) -> Option<Value> {
189	    let mut child = rex_command()
190	        .args(args)
191	        .stdout(Stdio::piped())
192	        .stderr(Stdio::null())
193	        .spawn()
194	        .ok()?;
195	    let stdout = child.stdout.take()?;
196	    let reader = std::thread::spawn(move || {
197	        let mut bytes = Vec::new();
198	        stdout.take(1024 * 1024 + 1).read_to_end(&mut bytes).ok()?;
199	        Some(bytes)
200	    });
201	    let deadline = Instant::now() + Duration::from_millis(800);
202	    loop {
203	        match child.try_wait().ok()? {
204	            Some(status) => {
205	                let bytes = reader.join().ok()??;
206	                return if status.success() && bytes.len() <= 1024 * 1024 {
207	                    serde_json::from_slice(&bytes).ok()
208	                } else {
209	                    None
210	                };
211	            }
212	            None if Instant::now() < deadline => std::thread::sleep(Duration::from_millis(10)),
213	            None => {
214	                let _ = child.kill();
215	                let _ = child.wait();
216	                return None;
217	            }
218	        }
219	    }
220	}
