225	    else {
226	        return Vec::new();
227	    };
228	    let mut targets = Vec::new();
229	    let started = Instant::now();
230	    for session in sessions.into_iter().take(32) {
231	        if started.elapsed() > Duration::from_secs(3) {
232	            break;
233	        }
234	        let Some(session_id) = session.get("session_id").and_then(Value::as_str) else {
235	            continue;
236	        };
237	        let Some(view) = rex_json(&["session", "inspect", session_id, "--json"]) else {
238	            continue;
239	        };
240	        let Some(windows) = view.get("windows").and_then(Value::as_array) else {
241	            continue;
242	        };
243	        for window in windows {
244	            let Some(layers) = window.get("layers").and_then(Value::as_array) else {
245	                continue;
246	            };
247	            for layer in layers {
248	                let Some(blocks) = layer.get("blocks").and_then(Value::as_array) else {
249	                    continue;
250	                };
251	                for block in blocks {
252	                    if started.elapsed() > Duration::from_secs(3) {
253	                        return targets;
254	                    }
255	                    let Some(block_id) = block.get("block_id").and_then(Value::as_str) else {
256	                        continue;
257	                    };
258	                    if block.get("creator_name").and_then(Value::as_str)
259	                        != Some("com.superlogical.terminal")
260	                    {
261	                        continue;
262	                    }
263	                    let process_arg = format!(r#"{{"block_id":"{block_id}"}}"#);
264	                    let process = rex_json(&[
265	                        "api",
266	                        "call",
267	                        "-s",
268	                        session_id,
269	                        "com.superlogical.terminal.process",
270	                        &process_arg,
271	                    ]);
272	                    let foreground = process.as_ref().and_then(|value| value.get("foreground"));
273	                    let process_name = foreground
274	                        .and_then(|value| value.get("name"))
275	                        .and_then(Value::as_str)
276	                        .map(str::to_string);
277	                    if !process_name
278	                        .as_deref()
279	                        .is_some_and(|name| name.eq_ignore_ascii_case("pi"))
280	                    {
281	                        continue;
282	                    }
283	                    let cwd = foreground
284	                        .and_then(|value| value.get("cwd"))
285	                        .and_then(Value::as_str)
286	                        .unwrap_or("");
287	                    if !compatible(project_root, cwd) {
288	                        continue;
289	                    }
290	                    let label = block
291	                        .get("label")
292	                        .and_then(Value::as_str)
293	                        .unwrap_or("Pi")
294	                        .to_string();
295	                    targets.push(AgentTarget {
296	                        id: format!("rex:{session_id}:{block_id}"),
297	                        label,
298	                        project_root: cwd.to_string(),
299	                        session_id: Some(session_id.to_string()),
300	                        block_id: Some(block_id.to_string()),
301	                        process: process_name,
302	                        busy: false,
303	                        connected: false,
304	                    });
305	                }
306	            }
307	        }
308	    }
309	    targets
310	}
