444	pub(crate) fn validate_batch(batch: &FeedbackBatch) -> Result<(), String> {
445	    if batch.source != "sidelit"
446	        || !safe_id(&batch.id)
447	        || batch.notes.is_empty()
448	        || batch.notes.len() > 20
449	        || serde_json::to_vec(batch).map_or(true, |bytes| bytes.len() > 30 * 1024)
450	    {
451	        return Err("Review batch must contain 1–20 notes and fit within 30 KiB".into());
452	    }
453	    let scope =
454	        note_scope(&batch.notes[0]).ok_or("Review notes need a project or live-page origin")?;
455	    let mut ids = std::collections::HashSet::new();
456	    for note in &batch.notes {
457	        validate_note(note, false)?;
458	        if !ids.insert(&note.id)
459	            || note.id == batch.id
460	            || note_scope(note).as_ref() != Some(&scope)
461	            || note.project_root != batch.project_root
462	        {
463	            return Err(
464	                "Review notes must have unique IDs and belong to one project or live-page origin"
465	                    .into(),
466	            );
467	        }
468	    }
469	    Ok(())
470	}
