30	export async function preparePreview(source: string, path: string, format: 'html' | 'mdx' | 'markdown', scripts: boolean, runtime: string, read: ReadAsset) {
31	  const markdown = format === 'markdown';
32	  if (markdown) {
33	    const reason = sourceReason(source, true);
34	    if (reason) throw new Error(reason);
35	    source = frontmatter(source).body;
36	  }
37	  const compiled = format !== 'html';
38	  let count = 0;
39	  let assetBytes = 0;
40	  const assets = new Map<string, Promise<PreviewAsset>>();
41	  const warnings: string[] = [];
42	  const asset = async (reference: string, base = path) => {
43	    if (++count > 256) throw new Error('Preview exceeds 256 local assets. Use a development server.');
44	    const key = new URL(reference, fileUrl(base)).href;
45	    if (assetBytes > 24 * 1024 * 1024) throw new Error('Preview asset budget exceeded. Use a development server.');
46	    if (!assets.has(key)) assets.set(key, read(path, key));
47	    const result = await assets.get(key)!;
48	    assetBytes += result.value.length;
49	    if (assetBytes > 24 * 1024 * 1024) throw new Error('Preview asset budget exceeded. Use a development server.');
50	    return result;
51	  };
52	  const image = async (ref: string, base = path) => {
53	    if (!isLocal(ref)) return ref;
54	    try { return (await asset(ref, base)).value; }
55	    catch (error) { warnings.push(`${ref}: ${String(error)}`); return 'data:,'; }
56	  };
57	  const css = async (text: string, base: string, depth = 0): Promise<string> => {
58	    if (depth > 8) throw new Error('Stylesheet import depth exceeded');
59	    const imports = [...text.matchAll(/@import\s+(?:url\(\s*)?['"]([^'"]+)['"]\s*\)?\s*([^;]*);/gi)];
60	    for (const match of imports) {
61	      if (!isLocal(match[1])) { warnings.push('Remote CSS import blocked: ' + match[1]); text = text.replace(match[0], ''); continue; }
62	      try {
63	        const sheet = await asset(match[1], base);
64	        let content = await css(sheet.value, sheet.path, depth + 1);
65	        if (match[2].trim()) content = `@media ${match[2]}{${content}}`;
66	        text = text.replace(match[0], content);
67	      } catch (error) { warnings.push(String(error)); text = text.replace(match[0], ''); }
68	    }
69	    const matches = [...text.matchAll(/url\(\s*['"]?([^'"\)]+?)['"]?\s*\)/gi)];
70	    for (const match of matches) if (isLocal(match[1])) text = text.replace(match[0], `url("${await image(match[1], base)}")`);
71	    return text;
72	  };
73	  let code = '';
74	  if (compiled) code = await (await import('./mdx')).compileStandaloneMdx(source, ref => image(ref), markdown ? 'md' : 'mdx');
75	  const parsed = new DOMParser().parseFromString(compiled ? '<div id="sidelit-root"></div>' : source, 'text/html');
76	  for (const node of [...parsed.querySelectorAll('base,iframe,frame,frameset,object,embed,portal,meta[http-equiv]')]) node.remove();
77	  for (const node of [...parsed.querySelectorAll('*')]) {
78	    for (const attr of [...node.attributes]) {
79	      if ((!scripts && /^on/i.test(attr.name)) || attr.name === 'srcdoc' || attr.name === 'nonce' || attr.name === 'integrity') node.removeAttribute(attr.name);
80	      if (/^(href|action|formaction)$/i.test(attr.name) && /^\s*(javascript|file|tauri|sidelit-preview):/i.test(attr.value)) node.removeAttribute(attr.name);
81	    }
82	  }
83	  for (const script of [...parsed.scripts]) {
84	    if (!scripts) { script.remove(); continue; }
85	    const src = script.getAttribute('src');
86	    if (src) {
87	      if (!isLocal(src)) { warnings.push('Remote script blocked: ' + src); script.remove(); continue; }
88	      try { script.textContent = safeScript((await asset(src)).value); script.removeAttribute('src'); }
89	      catch (error) { warnings.push(String(error)); script.remove(); }
90	    }
91	  }
92	  for (const link of [...parsed.querySelectorAll('link')]) {
93	    const href = link.getAttribute('href') || '';
94	    if (link.matches('[rel~="stylesheet"]') && !isLocal(href)) warnings.push('Remote stylesheet blocked: ' + href);
95	    if (!link.matches('[rel~="stylesheet"]') || !isLocal(href)) { link.remove(); continue; }
96	    try {
97	      const sheet = await asset(href); const style = parsed.createElement('style');
98	      style.textContent = await css(sheet.value, sheet.path); link.replaceWith(style);
99	    } catch (error) { warnings.push(String(error)); link.remove(); }
100	  }
101	  for (const element of [...parsed.querySelectorAll('img[src],source[src],video[poster]')]) {
102	    const name = element.hasAttribute('poster') ? 'poster' : 'src';
103	    element.setAttribute(name, await image(element.getAttribute(name) || ''));
104	  }
105	  for (const element of [...parsed.querySelectorAll('[srcset]')]) {
106	    const srcset = element.getAttribute('srcset')!;
107	    if (srcset.includes('data:')) continue;
108	    const entries = await Promise.all(srcset.split(',').map(async part => {
109	      const [ref, ...descriptor] = part.trim().split(/\s+/); return [await image(ref), ...descriptor].join(' ');
110	    }));
111	    element.setAttribute('srcset', entries.join(', '));
112	  }
113	  for (const style of [...parsed.querySelectorAll('style')]) style.textContent = await css(style.textContent || '', path);
114	  for (const element of [...parsed.querySelectorAll('[style]')]) element.setAttribute('style', await css(element.getAttribute('style')!, path));
115	  const nonce = crypto.randomUUID().replaceAll('-', '');
116	  const csp = parsed.createElement('meta'); csp.httpEquiv = 'Content-Security-Policy';
117	  csp.content = `default-src 'none'; script-src ${scripts || format === 'mdx' ? "'unsafe-inline' 'unsafe-eval'" : "'nonce-" + nonce + "'" + (markdown ? " 'unsafe-eval'" : "")}; style-src 'unsafe-inline'; img-src data:; font-src data:; connect-src 'none'; frame-src 'none'; object-src 'none'; base-uri 'none'; form-action 'none'`;
118	  parsed.head.prepend(csp);
119	  const addScript = (text: string, first = false) => { const script = parsed.createElement('script'); script.setAttribute('nonce', nonce); script.textContent = safeScript(text); if (first) csp.after(script); else parsed.body.append(script); };
120	  addScript(bridge, true);
121	  if (compiled) {
122	    const style = parsed.createElement('style'); style.textContent = mdxStyle; parsed.head.append(style);
123	    const data = parsed.createElement('script'); data.id = 'sidelit-mdx'; data.type = 'application/json'; data.textContent = JSON.stringify({ code }).replaceAll('<', '\\u003c'); parsed.body.append(data);
124	    addScript(runtime);
125	  }
126	  return { html: '<!doctype html>' + parsed.documentElement.outerHTML, warnings };
127	}
