1	import type { Opened, Snapshot, SaveResult, SavedDocument } from "./api";
2	import { sourceReason } from "./fidelity";
3	import { formatForPath, type DocumentFormat } from "./formats";
4	export type Mode = "rendered" | "source";
5	export interface Document {
6	  path: string;
7	  format: DocumentFormat;
8	  text: string;
9	  disk: Snapshot;
10	  revision: number;
11	  mode: Mode;
12	  reason?: string;
13	  previewOnly?: boolean;
14	  review?: Snapshot;
15	  pending?: { snapshot: Snapshot | null; error: string | null };
16	  saving: boolean;
17	  notice: string;
18	}
19	export const dirty = (doc: Document) => doc.text !== doc.disk.text;
20	function rendering(path: string, text: string, mode: Mode) {
21	  const editReason = mode === "rendered" && formatForPath(path) === "markdown"
22	    ? sourceReason(text)
23	    : undefined;
24	  // Diagrams and comments can be previewed safely, but must not enter the rich editor.
25	  const reason = editReason ? sourceReason(text, true) : undefined;
26	  return { mode: reason ? "source" as const : mode, reason, previewOnly: !!editReason && !reason };
27	}
28	export interface Transport {
29	  read(path: string): Promise<Snapshot>;
30	  save(path: string, expected: string, text: string): Promise<SaveResult>;
31	}
32	
33	export class Documents {
34	  docs: Document[] = [];
35	  private listeners = new Set<() => void>();
36	  private reads = new Map<string, number>();
37	  constructor(private transport: Transport) {}
38	  subscribe = (listener: () => void) => {
39	    this.listeners.add(listener);
40	    return () => {
41	      this.listeners.delete(listener);
42	    };
43	  };
44	  snapshot = () => this.docs;
45	  get = (path: string) => this.docs.find((d) => d.path === path);
46	  private emit() {
47	    this.listeners.forEach((fn) => fn());
48	  }
49	  update(path: string, change: Partial<Document>) {
50	    this.docs = this.docs.map((d) =>
51	      d.path === path ? { ...d, ...change } : d,
52	    );
53	    this.emit();
54	  }
55	  open(file: Opened, mode: Mode = "rendered") {
56	    if (this.get(file.path)) return;
57	    this.docs = [
58	      ...this.docs,
59	      {
60	        path: file.path,
61	        format: formatForPath(file.path) ?? "markdown",
62	        text: file.snapshot.text,
63	        disk: file.snapshot,
64	        revision: 0,
65	        ...rendering(file.path, file.snapshot.text, mode),
66	        saving: false,
67	        notice: "",
68	      },
69	    ];
70	    this.emit();
71	  }
72	  setMode(path: string, mode: Mode) {
73	    const doc = this.get(path);
74	    if (doc) this.update(path, rendering(path, doc.text, mode));
75	  }
76	  restore(saved: SavedDocument) {
77	    if (this.get(saved.path)) return;
78	    this.open({ path: saved.path, parent: "", snapshot: saved.disk }, "source");
79	    this.edit(saved.path, saved.text);
80	    this.setMode(saved.path, saved.mode);
81	    this.update(saved.path, { notice: "Restored session" });
82	  }
83	  edit(path: string, text: string) {
84	    const doc = this.get(path);
85	    if (!doc || doc.text === text) return;
86	    this.update(path, { text, revision: doc.revision + 1, notice: "", reason: undefined });
87	  }
88	  remove(path: string) {
89	    this.bump(path);
90	    this.docs = this.docs.filter((d) => d.path !== path);
91	    this.emit();
92	  }
93	  private bump(path: string) {
94	    const n = (this.reads.get(path) ?? 0) + 1;
95	    this.reads.set(path, n);
96	    return n;
97	  }
98	  async refresh(path: string, discard = false) {
99	    const before = this.get(path);
100	    if (!before) return;
101	    const token = this.bump(path);
102	    try {
103	      const disk = await this.transport.read(path);
104	      const doc = this.get(path);
105	      if (
106	        !doc ||
107	        token !== this.reads.get(path) ||
108	        doc.disk.hash !== before.disk.hash
109	      )
110	        return;
111	      if (discard && doc.revision !== before.revision)
112	        throw new Error("The draft changed during reload. Try again.");
113	      if (disk.hash === doc.disk.hash && !discard && !doc.pending) return;
114	      if (discard || !dirty(doc) || disk.text === doc.text) {
115	        this.update(path, {
116	          disk,
117	          text: disk.text,
118	          ...rendering(path, disk.text, doc.mode),
119	          review: !discard && disk.hash !== doc.disk.hash ? doc.disk : doc.review,
120	          pending: undefined,
121	          revision: doc.revision + (doc.text === disk.text ? 0 : 1),
122	          notice: disk.hash !== doc.disk.hash ? "Updated from disk" : "",
123	        });
124	      } else {
125	        this.update(path, {
126	          pending: { snapshot: disk, error: null },
127	          notice: "",
128	        });
129	      }
130	    } catch (e) {
131	      if (token === this.reads.get(path) && this.get(path))
132	        this.update(path, {
133	          pending: {
134	            snapshot: this.get(path)?.pending?.snapshot ?? null,
135	            error: String(e),
136	          },
137	        });
138	      if (discard) throw e;
139	    }
140	  }
141	  async save(path: string, reviewed?: Snapshot): Promise<boolean> {
142	    const before = this.get(path);
143	    if (!before || before.saving) return false;
144	    this.bump(path);
145	    this.update(path, { saving: true });
146	    try {
147	      const result = await this.transport.save(
148	        path,
149	        reviewed?.hash ?? before.disk.hash,
150	        before.text,
151	      );
152	      const doc = this.get(path);
153	      if (!doc) return false;
154	      this.bump(path);
155	      if (result.kind === "conflict") {
156	        this.update(path, {
157	          pending: {
158	            snapshot: result.snapshot ?? doc.pending?.snapshot ?? null,
159	            error: result.error,
160	          },
161	          notice: "",
162	        });
163	        return false;
164	      }
165	      this.update(path, {
166	        disk: result.snapshot,
167	        pending: undefined,
168	        notice:
169	          doc.text === before.text
170	            ? "Saved"
171	            : "Earlier revision saved; draft has newer edits",
172	      });
173	      await this.refresh(path);
174	      const current = this.get(path);
175	      return !!current && !dirty(current) && !current.pending;
176	    } finally {
177	      if (this.get(path)) this.update(path, { saving: false });
178	    }
179	  }
180	}
