5	const parser = unified().use(remarkParse).use(remarkGfm);
6	const supported = new Set([
7	  "root",
8	  "paragraph",
9	  "text",
10	  "heading",
11	  "strong",
12	  "emphasis",
13	  "delete",
14	  "list",
