27	export function frontmatter(text: string) {
28	  const opening = /^(---|\+\+\+)[ \t]*\r?\n/.exec(text);
29	  if (!opening) return { prefix: "", body: text, unclosed: false };
30	  const closing = opening[1] === "---"
31	    ? /^(?:---|\.\.\.)[ \t]*(?:\r?\n|$)/gm
32	    : /^\+\+\+[ \t]*(?:\r?\n|$)/gm;
33	  closing.lastIndex = opening[0].length;
34	  const end = closing.exec(text);
35	  if (!end) return { prefix: "", body: text, unclosed: true };
36	  let at = end.index + end[0].length;
37	  at += /^(?:[ \t]*\r?\n)*/.exec(text.slice(at))![0].length;
38	  return { prefix: text.slice(0, at), body: text.slice(at), unclosed: false };
39	}
40	
41	export function replaceBody(original: string, body: string) {
42	  const { prefix } = frontmatter(original);
43	  const separator = prefix && !prefix.endsWith("\n") && body
44	    ? original.includes("\r\n") ? "\r\n" : "\n"
45	    : "";
46	  return prefix + separator + lineEndings(body, original);
47	}
48	
49	export function sourceReason(text: string, preview = false): string | undefined {
50	  // Bound rich-editor work before parsing; Source can handle much larger files.
51	  if (text.length > 256 * 1024)
52	    return "Large documents use Source for responsive editing.";
53	  if (text.startsWith("\uFEFF"))
54	    return "A byte-order mark is preserved in Source mode.";
55	  const parts = frontmatter(text);
56	  if (parts.unclosed)
57	    return "Unclosed frontmatter is preserved in Source mode.";
58	  text = parts.body;
59	  let reason: string | undefined;
60	  const prose: string[] = [];
61	  let end = 0;
62	  const visit = (node: {
63	    type: string;
64	    value?: string;
65	    children?: unknown[];
66	    url?: string;
67	    lang?: string;
68	    meta?: string | null;
69	    position?: { start: { offset?: number }; end: { offset?: number } };
70	  }) => {
71	    const comment = preview && node.type === "html" && /^(?:<!--(?:(?!-->)[\s\S])*-->[ \t\r\n]*)+$/.test(node.value ?? "");
72	    if (node.type === "code" || node.type === "inlineCode" || comment) {
73	      const from = node.position?.start.offset;
74	      const to = node.position?.end.offset;
75	      if (from !== undefined && to !== undefined) {
76	        // Keep code and hidden comments opaque without creating new prose blocks.
77	        prose.push(text.slice(end, from), "`code`");
78	        end = to;
79	      }
80	    }
81	    if (!supported.has(node.type) && !comment)
82	      reason =
83	        "HTML, references, or extension syntax is preserved in Source mode.";
84	    if (node.type === "code" && ((!preview && node.lang === "mermaid") || node.meta))
85	      reason = "Diagram or code metadata is preserved in Source mode.";
86	    if (
87	      node.url &&
88	      /^[a-z][a-z\d+.-]*:/i.test(node.url) &&
89	      !/^(https?:|mailto:)/i.test(node.url)
90	    )
91	      reason = "This URL scheme cannot be used in rendered mode.";
92	    node.children?.forEach((child) =>
93	      visit(child as Parameters<typeof visit>[0]),
94	    );
95	  };
96	  visit(parser.parse(text));
97	  if (/\$|\\[([]|^\s*(?:::|\[\^)/m.test(prose.join("") + text.slice(end)))
98	    return "Math or extension syntax is preserved in Source mode.";
99	  return reason;
100	}
101	export function lineEndings(text: string, original: string) {
102	  return original.includes("\r\n") &&
103	    !original.replaceAll("\r\n", "").includes("\n")
104	    ? text.replace(/\r?\n/g, "\r\n")
105	    : text;
106	}
