23	const ACK_FLAG: &str = "--sidelit-handoff";
24	fn split_ack(mut args: Vec<String>) -> (Vec<String>, Option<PathBuf>) {
25	    let ack = if args.len() >= 2 && args[args.len() - 2] == ACK_FLAG {
26	        let path = PathBuf::from(args.pop().unwrap());
27	        args.pop();
28	        Some(path)
29	    } else {
30	        None
31	    };
32	    (args, ack)
33	}
34	fn acknowledge(path: Option<&Path>, result: Result<(), String>) {
35	    if let Some(path) = path {
36	        // The launcher owns this pre-created file; never create an arbitrary callback path.
37	        if path.parent() == Some(env::temp_dir().as_path())
38	            && path
39	                .file_name()
40	                .unwrap_or_default()
41	                .to_string_lossy()
42	                .starts_with("sidelit-handoff-")
43	        {
44	            if let Ok(mut file) = fs::OpenOptions::new().write(true).truncate(true).open(path) {
45	                let _ = file.write_all(match &result {
46	                    Ok(()) => b"OK",
47	                    Err(e) => e.as_bytes(),
48	                });
49	            }
50	        }
51	    }
52	}
53	fn main() {
54	    let args: Vec<String> = env::args().skip(1).collect();
55	    if args == ["--help"] || args == ["-h"] {
56	        println!("Sidelit — a visual companion for terminal development.\n\nUsage: sidelit [--source] [PATH]\n       sidelit setup [--pi] [--skill] [--dry-run] [--json]\n       sidelit doctor [--project DIR] [--json]\n       sidelit sessions [--project DIR] [--json]\n       sidelit --help\n       sidelit --version\n\nPATH is a Markdown, MDX, or HTML file, or a folder, relative to your current directory.\nRequests reuse the running app. The command returns after handoff.\nSetup installs bundled integrations without a checkout. Existing custom installations are preserved.\nDoctor is read-only; it never sends an agent instruction. JSON schema version: 1.\nExit codes: 0 success, 1 setup conflict or no healthy matching Pi (doctor), 2 invalid request/error.\nUse -- before a path named setup, doctor, or sessions.");
57	        return;
58	    }
59	    if args == ["--version"] {
60	        println!(
61	            "Sidelit {} ({})",
62	            env!("CARGO_PKG_VERSION"),
63	            env!("SIDELIT_BUILD_ID")
64	        );
65	        return;
66	    }
67	    let cwd = env::current_dir().unwrap_or_else(|_| PathBuf::from("/"));
68	    if let Some(code) = integrations::dispatch(&args, &cwd) {
69	        std::process::exit(code);
70	    }
71	    // Launch Services sends file-open events to its child, so only detach terminal launches.
72	    #[cfg(target_os = "macos")]
73	    let native_launch = unsafe { libc::getppid() == 1 };
74	    #[cfg(not(target_os = "macos"))]
75	    let native_launch = false;
76	    if env::var_os("SIDELIT_GUI").is_none() && !native_launch {
77	        if let Err(error) = cli::parse(&args, &cwd) {
78	            eprintln!("sidelit: {error}");
79	            std::process::exit(2);
80	        }
81	        let mut ack = tempfile::Builder::new()
82	            .prefix("sidelit-handoff-")
83	            .tempfile()
84	            .expect("create handoff receipt");
85	        // Start the real bundle even when the CLI was reached through a PATH symlink.
86	        let child = env::current_exe()
87	            .and_then(fs::canonicalize)
88	            .and_then(|executable| {
89	                Command::new(executable)
90	                    .args(&args)
91	                    .arg(ACK_FLAG)
92	                    .arg(ack.path())
93	                    .env("SIDELIT_GUI", "1")
94	                    .stdin(Stdio::null())
95	                    .stdout(Stdio::null())
96	                    .stderr(Stdio::null())
97	                    .spawn()
98	            });
99	        if let Err(error) = child {
100	            eprintln!("sidelit: {error}");
101	            std::process::exit(1);
102	        }
