70	      if (notStarted(previous)) return deliver(message, digest);
71	      return { ...previous.receipt, status: previous.receipt.status === 'accepted' ? 'duplicate' : 'received' };
72	    }
73	    if (seen.size >= 2000) throw new Error('Session feedback limit reached; start a new Pi session');
74	    return deliver(message, digest);
75	  };
