47	  snapshot = () => this.state;
48	  subscribe = (listener: () => void) => { this.listeners.add(listener); return () => { this.listeners.delete(listener); }; };
49	  private update(change: Partial<typeof this.state>) { this.state = { ...this.state, ...change }; this.listeners.forEach(fn => fn()); }
