61	  }
62	  private async commit(record: ReviewRecord) {
63	    await this.io.storeReview(record);
64	    this.update({ record });
65	  }
66	  private async run(action: () => Promise<void>) {
67	    if (!this.state.ready || this.state.busy) throw Error('Wait for review notes to finish loading or saving.');
68	    this.update({ busy: true, error: '' });
69	    try { await action(); }
70	    catch (error) { this.update({ error: String(error) }); throw error; }
71	    finally { this.update({ busy: false }); }
72	  }
73	  locked(id: string) { return !!this.state.record.attempt?.message.notes.some(note => note.id === id); }
74	  save(note: FeedbackMessage) {
