3	// Quote anchors deliberately refuse ambiguous matches rather than highlight the wrong passage.
4	export function locateSelection(root: Element, context: SelectionContext): Range | Element | null {
5	  if (context.type === 'element' && context.selector) {
6	    try {
7	      const el = root.ownerDocument.querySelector(context.selector);
8	      return el && root.contains(el) && el.tagName.toLowerCase() === context.tag
9	        && (el.id || undefined) === (context.id || undefined)
10	        && bounded(el.textContent ?? '', 800) === context.text
11	        && (context.classes ?? []).every(name => el.classList.contains(name)) ? el : null;
12	    } catch { return null; }
13	  }
14	  if (context.type !== 'text' || !context.text) return null;
15	  const quote = context.anchorText ?? context.text;
16	  if (!quote) return null;
17	  const walker = root.ownerDocument.createTreeWalker(root, NodeFilter.SHOW_TEXT);
18	  const nodes: Text[] = []; let text = '', node: Node | null;
19	  while ((node = walker.nextNode()) && nodes.length < 20000 && text.length < 2000000) {
20	    if (node.parentElement?.closest('[data-sidelit-overlay]')) continue;
21	    nodes.push(node as Text); text += node.textContent;
22	  }
23	  const matches: number[] = [];
24	  for (let from = 0, at; (at = text.indexOf(quote, from)) >= 0; from = at + 1) {
25	    if ((!context.prefix || text.slice(Math.max(0, at - context.prefix.length), at) === context.prefix)
26	      && (!context.suffix || text.slice(at + quote.length, at + quote.length + context.suffix.length) === context.suffix)) matches.push(at);
27	    if (matches.length > 1) return null;
28	  }
29	  const start = matches[0] ?? -1;
30	  if (start < 0) return null;
31	  const range = root.ownerDocument.createRange(); let offset = 0, started = false;
32	  for (const node of nodes) {
33	    const end = offset + node.length;
34	    if (!started && start < end) { range.setStart(node, start - offset); started = true; }
35	    if (started && start + quote.length <= end) { range.setEnd(node, start + quote.length - offset); return range; }
36	    offset = end;
37	  }
38	  return null;
39	}
