41	export function markSelection(root: Element, context: SelectionContext, reveal = false) {
42	  const target = locateSelection(root, context);
43	  if (!target) return () => {};
44	  const element = target instanceof Element ? target : target.startContainer.parentElement;
45	  if (reveal) element?.scrollIntoView({ block: 'center' });
