export const MAX_MATH_PER_DOCUMENT = 500;
// Pandoc's rule, plus no digit after the opening `$`, so money and shell variables stay text.
const inline = /(?<![\\$\w])\$\$(?=\S)([^$]{1,4000}?)\$\$(?!\$)|(?<![\\$\w])\$(?=[^\s\d$])([^$\n]{1,1000}?)(?<=[^\s\\])\$(?![\w$])/g;
