61	// Longest common subsequence of the differing middle; an oversized middle stays one change.
62	function matches(a: Block[], b: Block[]) {
63	  const pairs: [number, number][] = [];
64	  let start = 0;
65	  while (start < a.length && start < b.length && a[start].key === b[start].key) {
66	    pairs.push([start, start]);
67	    start++;
68	  }
69	  let endA = a.length, endB = b.length;
70	  while (endA > start && endB > start && a[endA - 1].key === b[endB - 1].key) { endA--; endB--; }
71	  const n = endA - start, m = endB - start;
72	  if (n && m && n * m <= LCS_CELLS) {
73	    const width = m + 1, table = new Uint32Array((n + 1) * width);
74	    for (let i = n - 1; i >= 0; i--)
75	      for (let j = m - 1; j >= 0; j--)
76	        table[i * width + j] = a[start + i].key === b[start + j].key
77	          ? table[(i + 1) * width + j + 1] + 1
78	          : Math.max(table[(i + 1) * width + j], table[i * width + j + 1]);
79	    for (let i = 0, j = 0; i < n && j < m;) {
80	      if (a[start + i].key === b[start + j].key) pairs.push([start + i++, start + j++]);
81	      else if (table[(i + 1) * width + j] >= table[i * width + j + 1]) i++;
82	      else j++;
83	    }
84	  }
85	  for (let i = endA, j = endB; i < a.length; i++, j++) pairs.push([i, j]);
86	  return pairs;
87	}
