100	export function computeChanges(before: string, after: string, format: DocumentFormat | "lines"): ChangeSet {
101	  const blocks = format === "markdown" ? markdownBlocks : lineBlocks;
102	  const a = blocks(before), b = blocks(after);
103	  const richBefore: number[] = [];
104	  let richCount = 0;
105	  for (const block of b) { richBefore.push(richCount); if (block.rich) richCount++; }
106	  const eol = after.includes("\r\n") ? "\r\n" : "\n";
107	  const gap = format === "markdown" ? eol + eol : eol;
108	  const changes: Change[] = [];
109	  let i = 0, j = 0;
110	  for (const [nextA, nextB] of [...matches(a, b), [a.length, b.length] as [number, number]]) {
111	    if (nextA > i || nextB > j) {
112	      const oldText = nextA > i ? before.slice(a[i].from, a[nextA - 1].to) : "";
113	      const added = nextB > j, removed = nextA > i;
114	      const from = added ? b[j].from : b[j]?.from ?? after.length;
115	      const to = added ? b[nextB - 1].to : from;
116	      const newText = after.slice(from, to);
117	      const previousEnd = j > 0 ? b[j - 1].to : undefined;
118	      const following = b[nextB]?.from;
119	      const revert = removed && added
120	        ? { from, to, text: oldText }
121	        : added
122	          ? following !== undefined
123	            ? { from, to: following, text: "" }
124	            : { from: previousEnd ?? from, to, text: "" }
125	          : following !== undefined || j < b.length
126	            ? { from, to: from, text: oldText + gap }
127	            : { from: previousEnd ?? after.length, to: previousEnd ?? after.length, text: (previousEnd === undefined ? "" : gap) + oldText };
128	      const line = lineAt(after, from);
129	      changes.push({
130	        kind: added && removed ? "changed" : added ? "added" : "removed",
131	        from, to, oldText, newText, line,
132	        endLine: line + (newText.match(/\n/g)?.length ?? 0),
133	        richFrom: richBefore[j] ?? richCount,
134	        richTo: richBefore[nextB] ?? richCount,
135	        label: excerpt(newText || oldText),
136	        revert,
137	      });
138	    }
139	    i = nextA + 1; j = nextB + 1;
140	  }
141	  return { changes, richCount };
142	}
