154	// What the file on disk lacks, in a form an agent can read beside that file.
155	export function draftChanges(disk: string, draft: string): { text: string; bytes: number } | undefined {
156	  const { changes } = computeChanges(disk, draft, "lines");
157	  if (!changes.length) return undefined;
158	  const lines = (prefix: string, text: string) => text ? text.split(/\r?\n/).map((line) => prefix + line) : [];
