1	import type { Opened, Snapshot, SaveResult, SavedDocument } from "./api";
2	import { sourceReason } from "./fidelity";
3	import { formatForPath, type DocumentFormat } from "./formats";
4	export type Mode = "rendered" | "source";
5	export interface Document {
6	  path: string;
7	  format: DocumentFormat;
8	  text: string;
9	  disk: Snapshot;
10	  revision: number;
11	  mode: Mode;
12	  reason?: string;
13	  // The version changes are marked against, kept until the person marks them reviewed.
14	  review?: Snapshot;
15	  reviewFrom?: "disk" | "commit";
16	  pending?: { snapshot: Snapshot | null; error: string | null };
17	  saving: boolean;
18	  notice: string;
19	}
20	export const dirty = (doc: Document) => doc.text !== doc.disk.text;
21	function rendering(path: string, text: string, mode: Mode) {
22	  const reason = mode === "rendered" && formatForPath(path) === "markdown"
23	    ? sourceReason(text)
24	    : undefined;
25	  return { mode: reason ? "source" as const : mode, reason };
26	}
27	export interface Transport {
28	  read(path: string): Promise<Snapshot>;
29	  save(path: string, expected: string, text: string): Promise<SaveResult>;
30	}
31	
32	export class Documents {
33	  docs: Document[] = [];
34	  private listeners = new Set<() => void>();
35	  private reads = new Map<string, number>();
36	  constructor(private transport: Transport) {}
37	  subscribe = (listener: () => void) => {
38	    this.listeners.add(listener);
39	    return () => {
40	      this.listeners.delete(listener);
41	    };
42	  };
43	  snapshot = () => this.docs;
44	  get = (path: string) => this.docs.find((d) => d.path === path);
45	  private emit() {
46	    this.listeners.forEach((fn) => fn());
47	  }
48	  update(path: string, change: Partial<Document>) {
49	    this.docs = this.docs.map((d) =>
50	      d.path === path ? { ...d, ...change } : d,
51	    );
52	    this.emit();
53	  }
54	  open(file: Opened, mode: Mode = "rendered") {
55	    if (this.get(file.path)) return;
56	    this.docs = [
57	      ...this.docs,
58	      {
59	        path: file.path,
60	        format: formatForPath(file.path) ?? "markdown",
61	        text: file.snapshot.text,
62	        disk: file.snapshot,
63	        revision: 0,
64	        ...rendering(file.path, file.snapshot.text, mode),
65	        saving: false,
66	        notice: "",
67	      },
68	    ];
69	    this.emit();
70	  }
71	  setMode(path: string, mode: Mode) {
72	    const doc = this.get(path);
73	    if (doc) this.update(path, rendering(path, doc.text, mode));
74	  }
75	  restore(saved: SavedDocument) {
76	    if (this.get(saved.path)) return;
77	    this.open({ path: saved.path, parent: "", snapshot: saved.disk }, "source");
78	    this.edit(saved.path, saved.text);
79	    this.setMode(saved.path, saved.mode);
80	    this.update(saved.path, { notice: "Restored session" });
81	  }
82	  edit(path: string, text: string) {
83	    const doc = this.get(path);
84	    if (!doc || doc.text === text) return;
85	    this.update(path, { text, revision: doc.revision + 1, notice: "", reason: undefined });
86	  }
87	  compareWithCommit(path: string, committed: Snapshot) {
88	    const doc = this.get(path);
89	    if (doc && !doc.review && committed.text !== doc.text)
90	      this.update(path, { review: committed, reviewFrom: "commit" });
91	  }
92	  remove(path: string) {
93	    this.bump(path);
94	    this.docs = this.docs.filter((d) => d.path !== path);
95	    this.emit();
96	  }
97	  private bump(path: string) {
98	    const n = (this.reads.get(path) ?? 0) + 1;
99	    this.reads.set(path, n);
100	    return n;
101	  }
102	  async refresh(path: string, discard = false) {
103	    const before = this.get(path);
104	    if (!before) return;
105	    const token = this.bump(path);
106	    try {
107	      const disk = await this.transport.read(path);
108	      const doc = this.get(path);
109	      if (
110	        !doc ||
111	        token !== this.reads.get(path) ||
112	        doc.disk.hash !== before.disk.hash
113	      )
114	        return;
115	      if (discard && doc.revision !== before.revision)
116	        throw new Error("The draft changed during reload. Try again.");
117	      if (disk.hash === doc.disk.hash && !discard && !doc.pending) return;
118	      if (discard || !dirty(doc) || disk.text === doc.text) {
119	        this.update(path, {
120	          disk,
121	          text: disk.text,
122	          ...rendering(path, disk.text, doc.mode),
123	          ...(!discard && disk.hash !== doc.disk.hash
124	            ? { review: doc.review ?? doc.disk, reviewFrom: doc.review ? doc.reviewFrom : "disk" as const }
125	            : {}),
126	          pending: undefined,
127	          revision: doc.revision + (doc.text === disk.text ? 0 : 1),
128	          notice: disk.hash !== doc.disk.hash ? "Updated from disk" : "",
129	        });
130	      } else {
131	        this.update(path, {
132	          pending: { snapshot: disk, error: null },
133	          notice: "",
134	        });
135	      }
136	    } catch (e) {
137	      if (token === this.reads.get(path) && this.get(path))
138	        this.update(path, {
139	          pending: {
140	            snapshot: this.get(path)?.pending?.snapshot ?? null,
141	            error: String(e),
142	          },
143	        });
144	      if (discard) throw e;
145	    }
146	  }
147	  async save(path: string, reviewed?: Snapshot): Promise<boolean> {
148	    const before = this.get(path);
149	    if (!before || before.saving) return false;
150	    this.bump(path);
151	    this.update(path, { saving: true });
152	    try {
153	      const result = await this.transport.save(
154	        path,
155	        reviewed?.hash ?? before.disk.hash,
156	        before.text,
157	      );
158	      const doc = this.get(path);
159	      if (!doc) return false;
160	      this.bump(path);
161	      if (result.kind === "conflict") {
162	        this.update(path, {
163	          pending: {
164	            snapshot: result.snapshot ?? doc.pending?.snapshot ?? null,
165	            error: result.error,
166	          },
167	          notice: "",
168	        });
169	        return false;
170	      }
171	      this.update(path, {
172	        disk: result.snapshot,
173	        pending: undefined,
174	        notice:
175	          doc.text === before.text
176	            ? "Saved"
177	            : "Earlier revision saved; draft has newer edits",
178	      });
179	      await this.refresh(path);
180	      const current = this.get(path);
181	      return !!current && !dirty(current) && !current.pending;
182	    } finally {
183	      if (this.get(path)) this.update(path, { saving: false });
184	    }
185	  }
186	}
