1	export interface Jump {
2	  nonce: number;
3	  path: string;
4	  text?: string;
5	  heading?: { index: number; line: number };
6	}
7	const claimed = new Map<string, number>();
8	// Editors remount on tab switches; returning to a tab must not repeat an old jump.
9	export function claimJump(jump: Jump | undefined, consumer: string): jump is Jump {
10	  if (!jump || claimed.get(consumer) === jump.nonce) return false;
11	  claimed.set(consumer, jump.nonce);
12	  return true;
13	}
