3	export default function ChangesBar({ changes, index, source, unmapped, canUndo, onGo, onRevert, onUndo, onCompare, onDone }: {
4	  changes: Change[]; index: number; source: "disk" | "commit" | undefined; unmapped: boolean; canUndo: boolean;
5	  onGo: (index: number) => void; onRevert: () => void; onUndo: () => void; onCompare: () => void; onDone: () => void;
6	}) {
7	  const current = changes[index];
8	  return <section className="changes-banner changes-bar" aria-label="Changes to review">
9	    <span className="changes-summary" role="status">
10	      <strong>{changes.length} {changes.length === 1 ? "change" : "changes"}</strong> since {source === "commit" ? "the last commit" : "you last reviewed"}
11	      {current && <span className="changes-current" title={current.label}> · {index + 1}: {current.kind === "removed" ? "removed " : ""}{current.label || "blank lines"}</span>}
12	      {unmapped && <span> · These can’t be marked in this view. Use Compare or Source.</span>}
13	    </span>
14	    <button disabled={changes.length < 2} title="Previous change (⇧F8)" aria-label="Previous change" onClick={() => onGo((index - 1 + changes.length) % changes.length)}>Previous</button>
15	    <button disabled={!changes.length} title="Next change (F8)" aria-label="Next change" onClick={() => onGo((index + 1) % changes.length)}>Next</button>
16	    {canUndo
17	      ? <button onClick={onUndo}>Undo revert</button>
18	      : <button disabled={!current} title="Put this passage back in your draft. Nothing is written until you save." onClick={onRevert}>Revert this</button>}
19	    <button onClick={onCompare}>Compare</button>
20	    <button onClick={onDone}>Mark reviewed</button>
21	  </section>;
22	}
