8	// libgit2, not the git command: a repository's own config can make `git status` run
9	// programs through core.fsmonitor or clean filters, and any folder can be opened here.
10	const MAX_FILES: usize = 2000;
11	const MAX_BLOB_BYTES: usize = 16 * 1024 * 1024;
12	
13	#[derive(Debug, Default, Serialize)]
14	#[serde(rename_all = "camelCase")]
15	pub struct GitStatus {
16	    files: Vec<GitFile>,
17	    incomplete: bool,
18	}
19	
20	#[derive(Debug, Serialize, PartialEq)]
21	pub struct GitFile {
22	    path: PathBuf,
23	    status: &'static str,
24	}
25	
26	fn workdir(repository: &Repository) -> Option<PathBuf> {
27	    files::canonical(repository.workdir()?).ok()
28	}
29	
30	fn label(status: Status) -> Option<&'static str> {
31	    if status.intersects(Status::WT_DELETED | Status::INDEX_DELETED) {
32	        None
33	    } else if status.intersects(Status::WT_NEW | Status::INDEX_NEW) {
34	        Some("added")
35	    } else {
36	        Some("modified")
37	    }
38	}
39	
40	fn changed_documents(root: &Path) -> GitStatus {
41	    let Ok(repository) = Repository::discover(root) else {
42	        return GitStatus::default();
43	    };
44	    let Some(base) = workdir(&repository) else {
45	        return GitStatus::default();
46	    };
47	    let mut options = StatusOptions::new();
48	    options
49	        .include_untracked(true)
50	        .recurse_untracked_dirs(true)
51	        .exclude_submodules(true);
52	    let Ok(statuses) = repository.statuses(Some(&mut options)) else {
53	        return GitStatus::default();
54	    };
55	    let mut result = GitStatus::default();
56	    for entry in statuses.iter() {
57	        let (Ok(relative), Some(status)) = (entry.path(), label(entry.status())) else {
58	            continue;
59	        };
60	        let path = base.join(relative);
61	        if !path.starts_with(root) || !files::supported_document(&path) {
62	            continue;
63	        }
64	        if result.files.len() == MAX_FILES {
65	            result.incomplete = true;
66	            break;
67	        }
68	        result.files.push(GitFile { path, status });
69	    }
70	    result
71	}
72	
73	fn committed_text(path: &Path) -> Option<Snapshot> {
74	    let repository = Repository::discover(path.parent()?).ok()?;
75	    let relative = path.strip_prefix(workdir(&repository)?).ok()?;
76	    let tree = repository.head().ok()?.peel_to_tree().ok()?;
77	    let blob = tree
78	        .get_path(relative)
79	        .ok()?
80	        .to_object(&repository)
81	        .ok()?
82	        .peel_to_blob()
83	        .ok()?;
84	    if blob.size() > MAX_BLOB_BYTES {
85	        return None;
86	    }
87	    Some(files::text_snapshot(
88	        std::str::from_utf8(blob.content()).ok()?,
89	    ))
90	}
