93	pub async fn git_status(state: State<'_, Service>, path: PathBuf) -> Result<GitStatus> {
94	    let root = state.allowed(&path)?;
95	    tauri::async_runtime::spawn_blocking(move || changed_documents(&root))
96	        .await
97	        .map_err(|e| e.to_string())
98	}
