5	#[derive(Clone, Debug, Serialize)]
6	#[serde(rename_all = "camelCase")]
7	pub struct Request {
8	    pub path: PathBuf,
9	    pub directory: bool,
10	    pub source: bool,
11	    pub find: Option<String>,
12	    pub anchor: Option<String>,
13	}
14	
15	const MAX_FIND_CHARS: usize = 300;
16	
17	pub fn parse(args: &[String], cwd: &Path) -> Result<Option<Request>> {
18	    let mut source = false;
19	    let mut path = None;
20	    let mut literal = false;
21	    let mut find = None;
22	    let mut args = args.iter();
23	    while let Some(arg) = args.next() {
24	        if !literal && arg == "--find" {
25	            let text = args.next().ok_or("--find needs the text to look for")?;
26	            if text.trim().is_empty() || text.chars().count() > MAX_FIND_CHARS {
27	                return Err(format!("--find needs 1 to {MAX_FIND_CHARS} characters"));
28	            }
29	            find = Some(text.clone());
30	            continue;
31	        }
32	        if !literal && arg == "--" {
33	            literal = true;
34	            continue;
35	        }
36	        if !literal && arg == "--source" {
37	            source = true;
38	            continue;
39	        }
40	        if !literal && arg.starts_with('-') {
41	            return Err(format!("Unknown option: {arg}. Use --help."));
42	        }
43	        if path.is_some() {
44	            return Err("Open one file or directory per CLI request".into());
45	        }
46	        path = Some(cwd.join(arg));
47	    }
48	    path.map(|p| {
49	        let path = canonical(&p)?;
50	        let directory = path.is_dir();
51	        if !directory && !supported_document(&path) {
52	            return Err("Choose a .md, .markdown, .mdx, .html, or .htm file".into());
53	        }
54	        if directory && source {
55	            return Err("--source requires a supported document file".into());
56	        }
57	        if directory && find.is_some() {
58	            return Err("--find requires a supported document file".into());
59	        }
60	        Ok(Request {
61	            path,
62	            directory,
63	            source,
64	            find: find.clone(),
65	            anchor: None,
66	        })
67	    })
68	    .transpose()
69	}
