44	impl Record {
45	    fn validate(&self) -> Result<()> {
46	        if self.version != 1 || self.notes.len() > 20 {
47	            return Err("Unsupported review record or more than 20 notes".into());
48	        }
49	        let mut ids = HashSet::new();
50	        for note in &self.notes {
51	            agents::validate_note(note, true)?;
52	            if !ids.insert(&note.id) {
53	                return Err("Duplicate review note ID".into());
54	            }
55	        }
56	        if let Some(attempt) = &self.attempt {
57	            agents::validate_batch(&attempt.message)?;
58	            if !agents::safe_id(&attempt.target)
59	                || attempt
60	                    .message
61	                    .notes
62	                    .iter()
63	                    .any(|note| !ids.contains(&note.id))
64	            {
65	                return Err("Invalid review delivery target or missing note".into());
66	            }
67	            if let Some(ack) = &attempt.ack {
68	                if ack.id != attempt.message.id
69	                    || !matches!(ack.status.as_str(), "received" | "accepted" | "duplicate")
70	                    || !matches!(ack.delivery.as_str(), "submitted" | "queued" | "consumed")
71	                {
72	                    return Err("Invalid review receipt".into());
73	                }
74	            }
75	        }
76	        Ok(())
77	    }
78	}
79	fn load(path: &Path) -> Result<Record> {
80	    if !path.try_exists().map_err(|e| e.to_string())? {
81	        return Ok(Record::default());
82	    }
83	    let record: Record = serde_json::from_slice(&files::read_bytes(path, MAX_BYTES)?)
84	        .map_err(|e| format!("Cannot read review notes: {e}. The saved file was not changed."))?;
85	    record.validate()?;
86	    Ok(record)
87	}
88	fn save(path: &Path, record: &Record) -> Result<()> {
89	    record.validate()?;
90	    let bytes = serde_json::to_vec(record).map_err(|e| e.to_string())?;
91	    if bytes.len() as u64 > MAX_BYTES {
92	        return Err("Review notes exceed 512 KiB; the previous notes were kept".into());
93	    }
94	    let parent = path.parent().ok_or("Missing review directory")?;
95	    // Only an explicit empty record can replace unreadable saved notes.
96	    if !record.notes.is_empty() {
97	        let old = load(path)?;
98	        if let Some(previous) = old.attempt {
99	            if let Some(next) = &record.attempt {
100	                if next.target != previous.target
101	                    || next.message != previous.message
102	                    || previous.message.notes.iter().any(|sent| {
103	                        old.notes.iter().find(|note| note.id == sent.id)
104	                            != record.notes.iter().find(|note| note.id == sent.id)
105	                    })
106	                {
107	                    return Err(
108	                        "A review delivery attempt cannot change its target or payload".into(),
109	                    );
110	                }
111	            } else if previous
112	                .message
113	                .notes
114	                .iter()
115	                .any(|sent| record.notes.iter().any(|note| note.id == sent.id))
116	            {
117	                return Err("Remove attempted notes together with their delivery record".into());
118	            }
119	        }
120	    }
121	    if record.notes.is_empty() {
122	        match fs::remove_file(path) {
123	            Ok(()) => {
124	                fs::File::open(parent)
125	                    .and_then(|f| f.sync_all())
126	                    .map_err(|e| e.to_string())?;
127	            }
128	            Err(e) if e.kind() == std::io::ErrorKind::NotFound => {}
129	            Err(e) => return Err(e.to_string()),
130	        }
131	        return Ok(());
132	    }
133	    fs::create_dir_all(parent).map_err(|e| e.to_string())?;
134	    #[cfg(unix)]
135	    {
136	        use std::os::unix::fs::PermissionsExt;
137	        fs::set_permissions(parent, fs::Permissions::from_mode(0o700))
138	            .map_err(|e| e.to_string())?;
139	    }
140	    let mut temp = tempfile::NamedTempFile::new_in(parent).map_err(|e| e.to_string())?;
141	    temp.write_all(&bytes)
142	        .and_then(|_| temp.as_file().sync_all())
143	        .map_err(|e| e.to_string())?;
144	    temp.persist(path).map_err(|e| e.to_string())?;
145	    fs::File::open(parent)
146	        .and_then(|f| f.sync_all())
147	        .map_err(|e| e.to_string())?;
148	    Ok(())
149	}
