41	// An agent's pointer, not captured identity: the first match is the useful answer here.
42	export function findText(root: Element, query: string): Range | null {
43	  const needle = query.trim();
44	  if (!needle) return null;
45	  const walker = root.ownerDocument.createTreeWalker(root, NodeFilter.SHOW_TEXT);
46	  const nodes: Text[] = []; let text = '', node: Node | null;
47	  while ((node = walker.nextNode()) && nodes.length < 20000 && text.length < 2000000) {
48	    if (node.parentElement?.closest('[data-sidelit-overlay]')) continue;
49	    nodes.push(node as Text); text += node.textContent;
50	  }
51	  let start = text.indexOf(needle);
52	  if (start < 0) start = text.toLowerCase().indexOf(needle.toLowerCase());
53	  if (start < 0) return null;
54	  const range = root.ownerDocument.createRange(); let offset = 0, started = false;
55	  for (const item of nodes) {
56	    const end = offset + item.length;
57	    if (!started && start < end) { range.setStart(item, start - offset); started = true; }
58	    if (started && start + needle.length <= end) { range.setEnd(item, start + needle.length - offset); return range; }
59	    offset = end;
60	  }
61	  return null;
62	}
63	
64	export function markSelection(root: Element, context: SelectionContext, reveal = false) {
65	  const target = locateSelection(root, context);
66	  return target ? markTarget(root, target, reveal) : () => {};
67	}
68	
69	export function markTarget(root: Element, target: Range | Element, reveal = false) {
70	  const element = target instanceof Element ? target : target.startContainer.parentElement;
71	  if (reveal) element?.scrollIntoView({ block: 'center' });
72	  const overlay = document.createElement('div'); overlay.dataset.sidelitOverlay = '';
73	  overlay.className = 'selection-highlight'; document.body.append(overlay);
74	  const draw = () => {
75	    overlay.replaceChildren();
76	    const clip = (root.closest('.rich-editor') ?? root).getBoundingClientRect();
77	    for (const rect of Array.from(target.getClientRects()).slice(0, 100)) {
78	      const left = Math.max(rect.left, clip.left), top = Math.max(rect.top, clip.top);
79	      const right = Math.min(rect.right, clip.right), bottom = Math.min(rect.bottom, clip.bottom);
80	      if (right <= left || bottom <= top) continue;
81	      const part = document.createElement('i');
82	      Object.assign(part.style, { left: left + 'px', top: top + 'px', width: right - left + 'px', height: bottom - top + 'px' });
83	      overlay.append(part);
84	    }
85	  };
86	  draw(); document.addEventListener('scroll', draw, true); window.addEventListener('resize', draw);
87	  const resize = new ResizeObserver(draw); resize.observe(root);
88	  return () => { overlay.remove(); resize.disconnect(); document.removeEventListener('scroll', draw, true); window.removeEventListener('resize', draw); };
89	}
