5	export function sessionSnapshot(documents: Documents, workspace: string, active: string, approvals: CloseApproval[] = []): Session {
6	  const discarded = new Set(approvals.filter((a) => a.discard).map((a) => a.path));
7	  const saved = documents.docs.filter((d) => !discarded.has(d.path)).map(({ path, text, disk, mode }) => ({ path, text, disk, mode }));
8	  return { documents: saved, workspace: workspace || null, active: saved.some((d) => d.path === active) ? active : saved.at(-1)?.path ?? null };
9	}
