11	export class RecoveryWriter {
12	  private running = false;
13	  private pending?: Session;
14	  private timer?: ReturnType<typeof setTimeout>;
15	  private writes?: Promise<void>;
16	  constructor(private write: (session: Session) => Promise<void>, private report: (error: unknown) => void) {}
17	  start() { this.running = true; }
18	  queue(session: Session) {
19	    if (!this.running) return;
20	    this.pending = session;
21	    // A fixed interval also checkpoints continuous typing, not only idle drafts.
22	    if (!this.writes) this.timer ??= setTimeout(() => { void this.flush().catch(this.report); }, 500);
23	  }
24	  flush(session?: Session): Promise<void> {
25	    clearTimeout(this.timer);
26	    this.timer = undefined;
27	    if (session && this.running) this.pending = session;
28	    if (!this.writes && this.running && this.pending) {
29	      this.writes = Promise.resolve().then(async () => {
30	        while (this.running && this.pending) {
31	          const next = this.pending;
32	          this.pending = undefined;
33	          await this.write(next);
34	        }
35	      }).finally(() => {
36	        this.writes = undefined;
37	        if (this.pending && this.running) this.queue(this.pending);
38	      });
39	    }
40	    return this.writes ?? Promise.resolve();
41	  }
42	  async stop() {
43	    this.running = false;
44	    clearTimeout(this.timer);
45	    this.timer = undefined;
46	    this.pending = undefined;
47	    await this.writes?.catch(() => {});
48	  }
49	}
