// Only in desktop-test builds. Test runs must not take focus or cover the person's work, so the
// app runs as a background process with its window off every screen. SIDELIT_TEST_VISIBLE=1
// shows a normal window, for watching a test.
use tauri::{Runtime, WebviewWindow};

const OFF_SCREEN: f64 = -20000.0;

pub fn background() -> bool {
    std::env::var_os("SIDELIT_TEST_VISIBLE").is_none()
}

pub fn position() -> (f64, f64) {
    (OFF_SCREEN, OFF_SCREEN)
}

// WebKit stops drawing, and pauses animation frames and timers, for a window it thinks nobody can
// see. These are private switches, fine here because this file never reaches a real build.
pub fn keep_running<R: Runtime>(window: &WebviewWindow<R>) {
    #[cfg(target_os = "macos")]
    {
        use objc2::{class, msg_send, runtime::AnyObject, sel};
        use objc2_foundation::NSString;
        let _ = window.with_webview(|webview| unsafe {
            let view: *mut AnyObject = webview.inner().cast();
            let selector = sel!(_setWindowOcclusionDetectionEnabled:);
            let available: bool = msg_send![view, respondsToSelector: selector];
            assert!(available, "WebKit no longer offers occlusion control");
            let _: () = msg_send![view, _setWindowOcclusionDetectionEnabled: false];
        });
        unsafe {
            let info: *mut AnyObject = msg_send![class!(NSProcessInfo), processInfo];
            let reason = NSString::from_str("Sidelit desktop test");
            // NSActivityUserInitiatedAllowingIdleSystemSleep; held until the process exits.
            let activity: *mut AnyObject =
                msg_send![info, beginActivityWithOptions: 0x00EF_FFFF_u64, reason: &*reason];
            let _: *mut AnyObject = msg_send![activity, retain];
        }
    }
    #[cfg(not(target_os = "macos"))]
    let _ = window;
}
