"""Fails a test run that took focus from whatever the person was doing."""
import plistlib
import subprocess
import threading
import time
from pathlib import Path


def _front():
    asn = subprocess.run(['lsappinfo', 'front'], capture_output=True, text=True).stdout.strip()
    info = subprocess.run(['lsappinfo', 'info', '-only', 'bundleid', asn], capture_output=True, text=True).stdout
    return info.split('=', 1)[-1].strip().strip('"')


class FocusGuard:
    def __init__(self, binary):
        contents = Path(binary).resolve().parents[1]
        with open(contents / 'Info.plist', 'rb') as info:
            self.identifier = plistlib.load(info)['CFBundleIdentifier']
        self.samples = 0
        self.stolen = 0
        self.running = True
        threading.Thread(target=self._watch, daemon=True).start()

    def _watch(self):
        while self.running:
            self.samples += 1
            if _front() == self.identifier:
                self.stolen += 1
            time.sleep(.1)

    def check(self, window_rect=None):
        """Call at the end of a run, with the window's WebDriver rect if there is one."""
        self.running = False
        assert not self.stolen, f'{self.identifier} was frontmost in {self.stolen} of {self.samples} samples'
        assert self.samples > 0
        if window_rect:
            assert window_rect['x'] + window_rect['width'] < 0, f'the test window is on a screen: {window_rect}'
        return {'focusSamples': self.samples, 'focusStolen': self.stolen}
